// release is one Xray release the test can run.
type release struct {
	version    string
	binary     string
	restricted bool
}

// releases are the Xray binaries named in the environment, recommended first.
func releases(t *testing.T) []release {
	t.Helper()
	var found []release
	for _, entry := range []struct {
		env, version string
		restricted   bool
	}{
		{"PSP_TEST_XRAY_26627_BIN", "26.6.27", false}, {"PSP_TEST_XRAY_26728_BIN", "26.7.28", false},
		{"PSP_TEST_XRAY_2699_BIN", "26.9.9", true}, {"PSP_TEST_XRAY_26119_BIN", "26.11.9", true},
	} {
		if binary, ok := os.LookupEnv(entry.env); ok {
			found = append(found, release{entry.version, binary, entry.restricted})
		}
	}
	if len(found) == 0 {
		t.Skip("set PSP_TEST_XRAY_26627_BIN (and PSP_TEST_XRAY_CLIENT_BIN) to run the SNI front matrix")
	}
	return found
}

func primary(t *testing.T) release { return releases(t)[0] }

func clientBinary(t *testing.T) string {
	t.Helper()
	if binary, ok := os.LookupEnv("PSP_TEST_XRAY_CLIENT_BIN"); ok {
		return binary
	}
	if binary, ok := os.LookupEnv("PSP_TEST_XRAY_26627_BIN"); ok {
		return binary
	}
	t.Skip("set PSP_TEST_XRAY_CLIENT_BIN (or PSP_TEST_XRAY_26627_BIN) for the client")
	return ""
}

// nonLoopbackIP is an address of this machine that is not loopback: the front's
// external default may not be one.
func nonLoopbackIP(t *testing.T) string {
	t.Helper()
	addresses, _ := net.InterfaceAddrs()
	for _, address := range addresses {
		if network, ok := address.(*net.IPNet); ok && network.IP.To4() != nil && !network.IP.IsLoopback() {
			return network.IP.String()
		}
	}
	t.Skip("no non-loopback IPv4 address for the external default")
	return ""
}

// layout is every port and address one front core is compiled for.
type layout struct {
	frontPort, loopOne, loopTwo, landingPort int
	decoy, relayTarget                       string
	external                                 protocol.FrontExternal
	// defaultListener makes lst_1 the default instead of the external site.
	defaultListener bool
}

func realityListener(number int64, port int, sni, decoy string) protocol.Listener {
	stream, _ := json.Marshal(map[string]any{"network": "raw", "security": "reality", "realitySettings": map[string]any{
		"target": decoy, "serverNames": []string{sni}, "privateKey": realityPrivate, "shortIds": []string{shortID}}})
	config, _ := json.Marshal(map[string]any{
		"enabled": true, "port": port, "protocol": "vless",
		"settings": `{"decryption":"none"}`, "stream_settings": string(stream),
	})
	return protocol.Listener{Key: protocol.NewListenerKey(number), Config: config}
}

func visionClient(number, listener int64, email, uuid string) protocol.Client {
	return protocol.Client{
		Key: protocol.NewClientKey(number), Subject: protocol.NewSubjectKey(number), Enabled: true,
		Listeners:   []protocol.ListenerKey{protocol.NewListenerKey(listener)},
		Credentials: protocol.Credential{Username: email, UUID: uuid, Flow: "xtls-rprx-vision"},
	}
}

// frontTransit is the front under test: two REALITY listeners, a raw relay, an
// incoming link and an external default, all on one port.
func frontTransit(l layout) *protocol.Transit {
	forward := protocol.NewForwardKey(1)
	link := protocol.NewLinkKey(5)
	fallback := protocol.FrontTarget{External: &l.external}
	if l.defaultListener {
		fallback = protocol.FrontTarget{Listener: protocol.NewListenerKey(1)}
	}
	return &protocol.Transit{
		Forwards: []protocol.Forward{{Key: forward, Port: l.frontPort, Target: "127.0.0.1", TargetPort: portOf(l.relayTarget), Network: protocol.ForwardNetworkTCP}},
		LinksIn: []protocol.LinkIn{{Key: link, Port: l.frontPort, Protocol: protocol.LinkProtocolVLESSReality, Reality: &protocol.LinkRealityServer{
			UUID: linkUUID, PrivateKey: realityPrivate, Target: l.decoy, ServerNames: []string{sniLink}, ShortIDs: []string{shortID}}}},
		Fronts: []protocol.Front{{
			Key: protocol.NewFrontKey(1), Port: l.frontPort,
			Listeners: []protocol.FrontedListener{
				{Listener: protocol.NewListenerKey(1), LoopbackPort: l.loopOne},
				{Listener: protocol.NewListenerKey(2), LoopbackPort: l.loopTwo},
			},
			Routes: []protocol.FrontRoute{
				{ServerNames: []string{sniOwn}, Target: protocol.FrontTarget{Listener: protocol.NewListenerKey(1)}},
				{ServerNames: []string{sniOwn2}, Target: protocol.FrontTarget{Listener: protocol.NewListenerKey(2)}},
				{ServerNames: []string{sniRelay}, Target: protocol.FrontTarget{Forward: forward}},
				{ServerNames: []string{sniLink}, Target: protocol.FrontTarget{Link: link}},
			},
			Default: fallback,
		}},
		Probe: &protocol.ProbeSettings{IntervalSeconds: 30, TimeoutMS: 3000, Forwards: []protocol.ProbeTarget{{Key: forward, Method: protocol.ProbeMethodTLS}}},
	}
}

func frontSnapshot(l layout, policy *protocol.DestinationPolicy) agentcore.Snapshot {
	return agentcore.Snapshot{
		Now: time.Now(),
		Listeners: []protocol.Listener{
			realityListener(1, l.frontPort, sniOwn, l.decoy), realityListener(2, l.frontPort, sniOwn2, l.decoy),
		},
		Clients:           []protocol.Client{visionClient(1, 1, emailOne, uuidOne), visionClient(2, 2, emailTwo, uuidTwo)},
		DestinationPolicy: policy,
		Transit:           frontTransit(l),
	}
}

func portOf(addr string) int {
	_, text, _ := net.SplitHostPort(addr)
	var port int
	_, _ = fmt.Sscanf(text, "%d", &port)
	return port
}

// allowLoopback lets the freedom outbounds the test points at loopback sites
// reach them, which Xray refuses for proxied traffic by default: the user's
// own "direct", a forward's outbound and the external default (each of them
// stands for a site elsewhere). The outbounds a front hands a listener or a
// link to are left exactly as compiled: they must carry their own permission.
func allowLoopback(t *testing.T, compiled []byte) []byte {
	t.Helper()
	var config map[string]any
	if err := json.Unmarshal(compiled, &config); err != nil {
		t.Fatal(err)
	}
	for _, raw := range config["outbounds"].([]any) {
		outbound := raw.(map[string]any)
		tag, _ := outbound["tag"].(string)
		isForward := len(tag) > len("transit-fwd_") && tag[:len("transit-fwd_")] == "transit-fwd_"
		isExternal := len(tag) > len("-external") && tag[len(tag)-len("-external"):] == "-external"
		if outbound["protocol"] != "freedom" || (tag != "direct" && !isForward && !isExternal) {
			continue
		}
		settings, _ := outbound["settings"].(map[string]any)
		if settings == nil {
			settings = map[string]any{}
		}
		settings["finalRules"] = []any{map[string]any{"action": "allow", "network": "tcp,udp"}}
		outbound["settings"] = settings
	}
	encoded, err := json.Marshal(config)
	if err != nil {
		t.Fatal(err)
	}
	return encoded
}

func compile(t *testing.T, r release, snapshot agentcore.Snapshot, apiPort int) agentcore.Artifact {
	t.Helper()
	artifact, err := (xray.Compiler{
		APIListen: fmt.Sprintf("127.0.0.1:%d", apiPort), CoreVersion: r.version, AllowRestrictedReality: r.restricted,
	}).Compile(context.Background(), snapshot)
	if err != nil {
		t.Fatal(err)
	}
	return artifact
}

type rigOptions struct {
	release release
	// policy is the destination policy of the front core, given the layout it is
	// compiled for.
	policy func(layout) *protocol.DestinationPolicy
	// defaultListener sends what no route names to lst_1.
	defaultListener bool
}

// rig is a front core compiled from a snapshot, a landing core behind its
// forward, and the sites around them.
type rig struct {
	t        *testing.T
	release  release
	layout   layout
	snapshot agentcore.Snapshot
	artifact agentcore.Artifact
	front    *policylive.Process
	landing  *policylive.Process
	frontAPI int

	decoy, site *site
	target      string
	teeL        *tee // between the front's forward and the landing
	teeC        *tee // between a client and the front
	baseline    int  // default-site connections made by the readiness probe
	decoyBase   int  // REALITY target probes the cores made while starting
}

func newRig(t *testing.T, o rigOptions) *rig {
	t.Helper()
	if o.release.binary == "" {
		o.release = primary(t)
	}
	r := &rig{t: t, release: o.release}
	r.decoy = newSite(t, "decoy.example.com", "127.0.0.1")
	r.site = newSite(t, "default.example.com", nonLoopbackIP(t))
	r.target = newTarget(t)
	r.layout = layout{
		frontPort: policylive.FreePort(t), loopOne: policylive.FreePort(t), loopTwo: policylive.FreePort(t), landingPort: policylive.FreePort(t),
		decoy: r.decoy.addr, external: protocol.FrontExternal{Host: hostOf(r.site.addr), Port: portOf(r.site.addr)},
		defaultListener: o.defaultListener,
	}
	r.frontAPI = policylive.FreePort(t)

	// The landing: its own core, one REALITY listener for the relayed SNI.
	landingSnapshot := agentcore.Snapshot{
		Now:       time.Now(),
		Listeners: []protocol.Listener{realityListener(1, r.layout.landingPort, sniRelay, r.decoy.addr)},
		Clients:   []protocol.Client{visionClient(1, 1, "land@x", uuidOne)},
	}
	landing := compile(t, o.release, landingSnapshot, policylive.FreePort(t))
	r.landing = policylive.Start(t, o.release.binary, "run", "-config", policylive.WriteFile(t, "landing.json", allowLoopback(t, landing.Config)))
	policylive.WaitListening(t, fmt.Sprintf("127.0.0.1:%d", r.layout.landingPort), r.landing)
	r.teeL = newTee(t, fmt.Sprintf("127.0.0.1:%d", r.layout.landingPort))
	r.layout.relayTarget = r.teeL.addr()

	var policy *protocol.DestinationPolicy
	if o.policy != nil {
		policy = o.policy(r.layout)
	}
	r.snapshot = frontSnapshot(r.layout, policy)
	r.artifact = compile(t, o.release, r.snapshot, r.frontAPI)
	r.front = policylive.Start(t, o.release.binary, "run", "-config", policylive.WriteFile(t, "front.json", allowLoopback(t, r.artifact.Config)))
	policylive.WaitListening(t, r.frontAddr(), r.front)
	r.teeC = newTee(t, r.frontAddr())
	// The readiness probe is a silent connection to the front, which falls
	// through to the default after the sniff gives up; let it land so tests
	// count only their own.
	// Wait for it rather than for a fixed time: on a loaded machine the sniff
	// gives up late, and a late arrival would be counted as a test's own.
	r.site.waitAccept(0, 15*time.Second)
	time.Sleep(300 * time.Millisecond)
	r.baseline = r.site.count()
	r.decoyBase = r.decoy.count()
	return r
}

func hostOf(addr string) string {
	host, _, _ := net.SplitHostPort(addr)
	return host
}

func (r *rig) frontAddr() string { return fmt.Sprintf("127.0.0.1:%d", r.layout.frontPort) }

func (r *rig) defaultHits() int { return r.site.count() - r.baseline }

// decoyHits are connections the REALITY target got since the cores started: the
// cores check their target as they start, which is not traffic.
func (r *rig) decoyHits() int { return r.decoy.count() - r.decoyBase }

func (r *rig) dump() string {
	return "front:\n" + r.front.Output() + "\nlanding:\n" + r.landing.Output()
}

type clientOptions struct {
	serverHost string // default 127.0.0.1
	serverPort int
	sni        string
	uuid       string
	sourceIP   string
}

// client starts a real Xray client (VLESS, REALITY, XTLS Vision) against the
// server port and returns its SOCKS port.
func (r *rig) client(o clientOptions) int {
	r.t.Helper()
	if o.uuid == "" {
		o.uuid = uuidOne
	}
	if o.serverHost == "" {
		o.serverHost = "127.0.0.1"
	}
	socks := policylive.FreePort(r.t)
	outbound := map[string]any{
		"tag": "p", "protocol": "vless",
		"settings": map[string]any{"vnext": []any{map[string]any{"address": o.serverHost, "port": o.serverPort,
			"users": []any{map[string]any{"id": o.uuid, "encryption": "none", "flow": "xtls-rprx-vision"}}}}},
		"streamSettings": map[string]any{"network": "raw", "security": "reality", "realitySettings": map[string]any{
			"serverName": o.sni, "fingerprint": "chrome", "publicKey": realityPublic, "shortId": shortID}},
	}
	if o.sourceIP != "" {
		outbound["sendThrough"] = o.sourceIP
	}
	body, _ := json.Marshal(map[string]any{
		"log":       map[string]any{"loglevel": "warning"},
		"inbounds":  []any{map[string]any{"listen": "127.0.0.1", "port": socks, "protocol": "socks", "settings": map[string]any{"udp": false}}},
		"outbounds": []any{outbound},
	})
	process := policylive.Start(r.t, clientBinary(r.t), "run", "-config", policylive.WriteFile(r.t, "client.json", body))
	policylive.WaitListening(r.t, fmt.Sprintf("127.0.0.1:%d", socks), process)
	return socks
}

// meter runs the node's own Xray telemetry against the running front core, with
// a scratch state store, and returns what a report would carry now.
func (r *rig) meter() func() (agentcore.Counters, error) {
	r.t.Helper()
	store, err := statesqlite.Open(r.t.Context(), filepath.Join(r.t.TempDir(), "state.db"))
	if err != nil {
		r.t.Fatal(err)
	}
	r.t.Cleanup(func() { _ = store.Close() })
	configBody, _ := json.Marshal(protocol.ConfigBody{Listeners: r.snapshot.Listeners, Transit: r.snapshot.Transit})
	rosterBody, _ := json.Marshal(protocol.RosterBody{Clients: r.snapshot.Clients})
	if err := store.SaveCoreDeployment(r.t.Context(), state.CoreDeployment{
		Engine: "xray", Version: r.release.version, ConfigDigest: r.artifact.Digest, Artifact: r.artifact.Config,
		ConfigBody: configBody, RosterBody: rosterBody, AppliedAtMS: 1,
	}); err != nil {
		r.t.Fatal(err)
	}
	status := agentcore.Status{
		State: agentcore.ProcessRunning, Engine: "xray", Version: r.release.version, BinaryPath: r.release.binary,
		ConfigDigest: r.artifact.Digest, LastChangedAt: time.Unix(2, 0),
	}
	telemetry, err := xray.NewTelemetry(xray.TelemetryOptions{
		Store: store, Status: func() agentcore.Status { return status },
		APIListen: fmt.Sprintf("127.0.0.1:%d", r.frontAPI), CommandTimeout: 5 * time.Second,
	})
	if err != nil {
		r.t.Fatal(err)
	}
	return func() (agentcore.Counters, error) { return telemetry.Collect(r.t.Context()) }
}

func waitCounters(t *testing.T, collect func() (agentcore.Counters, error), dump func() string, ok func(agentcore.Counters) bool) agentcore.Counters {
	t.Helper()
	deadline := time.Now().Add(15 * time.Second)
	for {
		counters, err := collect()
		if err == nil && ok(counters) {
			return counters
		}
		if time.Now().After(deadline) {
			t.Fatalf("counters never settled: %+v (%v)\n%s", counters, err, dump())
		}
		time.Sleep(200 * time.Millisecond)
	}
}

// xrayStats runs `xray api statsquery` against the front core's API.
func xrayStats(t *testing.T, r release, port int) map[string]int64 {
	t.Helper()
	out, err := exec.Command(r.binary, "api", "statsquery", "--server=127.0.0.1:"+strconv.Itoa(port), "--timeout=5").CombinedOutput()
	if err != nil {
		t.Fatalf("xray api statsquery: %v\n%s", err, out)
	}
	var response struct {
		Stat []struct {
			Name  string `json:"name"`
			Value any    `json:"value"`
		} `json:"stat"`
	}
	if err := json.Unmarshal(out, &response); err != nil {
		t.Fatal(err)
	}
	stats := map[string]int64{}
	for _, s := range response.Stat {
		switch v := s.Value.(type) {
		case string:
			n, _ := strconv.ParseInt(v, 10, 64)
			stats[s.Name] = n
		case float64:
			stats[s.Name] = int64(v)
		}
	}
	return stats
}
